function zigzagRows(text: string, rows: number): string {
  const n = text.length;
  const grid: string[][] = Array.from({ length: rows }, () => new Array(n).fill(""));
  let r = 0, c = 0, down = true;
  for (const ch of text) {
    grid[r][c] = ch;
    if (rows === 1) { c++; continue; }
    if (down && r === rows - 1) down = false;
    else if (!down && r === 0) down = true;
    if (down) r++;
    else { r--; c++; }
  }
  return grid.map(row => row.join("")).join("");
}

