class Solution:
    def zigzagRows(self, text: str, rows: int) -> str:
        n = len(text)
        grid = [[""] * n for _ in range(rows)]
        r = c = 0
        down = True
        for ch in text:
            grid[r][c] = ch
            if rows == 1:
                c += 1
                continue
            if down and r == rows - 1:
                down = False
            elif not down and r == 0:
                down = True
            if down:
                r += 1
            else:
                r -= 1
                c += 1
        return "".join("".join(row) for row in grid)

