function zigzagRows(text: string, rows: number): string {
  const n = text.length;
  if (rows === 1 || n <= rows) return text;
  const cycle = 2 * rows - 2;
  const out: string[] = [];
  for (let r = 0; r < rows; r++) {
    for (let start = 0; start + r < n; start += cycle) {
      out.push(text[start + r]);
      const up = start + cycle - r; // the character placed on the way back up
      if (r > 0 && r < rows - 1 && up < n) out.push(text[up]);
    }
  }
  return out.join("");
}

