        for r in range(rows):
            for start in range(0, n - r, cycle):
                out.append(text[start + r])
                up = start + cycle - r  # the character placed on the way back up
                if 0 < r < rows - 1 and up < n:
                    out.append(text[up])
        return "".join(out)

